&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Own the key cross functional business meetings, from planning through to follow through&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:220,&amp;quot;335559739&amp;quot;:220}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
