&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;4 to 7 years in FP&amp;amp;A, strategic finance, business operations, consulting, or a comparable chief of staff role&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:200,&amp;quot;335559739&amp;quot;:200}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
