&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Detail-oriented with&amp;nbsp;a strong sense&amp;nbsp;of ownership and accountability&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:200,&amp;quot;335559739&amp;quot;:60}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
