&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Diplomacy and patience when working through customer issues&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:220,&amp;quot;335559739&amp;quot;:220}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Comfortable communicating with anyone, from&amp;nbsp;foremen&amp;nbsp;to senior-level managers&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:220,&amp;quot;335559739&amp;quot;:220}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
